            description="The FULL URL of your Flogo MCP Server ending in /mcp",
        )

    def __init__(self):
        self.valves = self.Valves()

    def _mcp_request(self, method: str, params: dict = None) -> dict:
        """
        Handles the persistent session handshake and SSE stream parsing
        required by the Flogo/Azure MCP implementation.
        """
        mcp_endpoint = self.valves.mcp_url.strip()

        # Mandatory headers verified in standalone testing
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "User-Agent": "open-webui-flogo-bridge/1.0",
        }

        # Use a session to ensure the mcp-session-id persists across the handshake
        with requests.Session() as session:
            session.verify = False
            session.headers.update(headers)

            try:
                # STEP 1: Initialize
                init_payload = {
                    "jsonrpc": "2.0",
                    "id": 1,
                    "method": "initialize",
                    "params": {
                        "protocolVersion": "2024-11-05",
                        "capabilities": {},
                        "clientInfo": {"name": "open-webui", "version": "1.0.0"},
                    },
                }
                init_res = session.post(mcp_endpoint, json=init_payload, timeout=10)

                # Capture the Session ID from headers (CRITICAL for Azure/Flogo)
                session_id = init_res.headers.get("mcp-session-id")
                if session_id:
                    session.headers.update({"mcp-session-id": session_id})

                # STEP 2: Initialized Notification
                notif_payload = {
                    "jsonrpc": "2.0",
                    "method": "notifications/initialized",
                    "params": {},
                }
                session.post(mcp_endpoint, json=notif_payload, timeout=5)

                # STEP 3: State Transition Delay
                # Azure containers need a moment to move from 'initializing' to 'running'
                time.sleep(2.5)

                # STEP 4: The Actual Call
                call_payload = {
                    "jsonrpc": "2.0",
                    "id": 2,
                    "method": method,
                    "params": params or {},
                }

                # We MUST use stream=True to read from the SSE (Server-Sent Events) stream
                response = session.post(
                    mcp_endpoint, json=call_payload, timeout=30, stream=True
                )

                if response.status_code not in [200, 202]:
                    return {
                        "error": f"Server returned {response.status_code}: {response.text}"
                    }

                # Parse the SSE stream for the 'data:' line
                for line in response.iter_lines():
                    if line:
                        decoded_line = line.decode("utf-8").strip()
                        if decoded_line.startswith("data:"):
                            json_str = decoded_line.replace("data:", "").strip()
                            return json.loads(json_str)

                return {
                    "error": "Handshake succeeded but no data was found in the SSE stream."
                }

            except Exception as e:
                return {"error": f"Protocol failure: {str(e)}"}

    def list_available_tools(self) -> str:
        """
        Discover tools on the Flogo MCP server. Run this if you are unsure of capabilities.
        """
        response = self._mcp_request("tools/list")
        if "error" in response:
            return f"Discovery failed: {response['error']}"

        result = response.get("result", {})
        tools = result.get("tools", [])
        if not tools:
            return "Connected to Flogo, but no tools were returned."

        tool_names = [t["name"] for t in tools]
        return f"Successfully connected to Flogo. Available tools: {', '.join(tool_names)}."

    def execute_mcp_tool(self, tool_name: str, arguments: dict = None) -> str:
        """
        Execute a specific Flogo MCP tool (e.g. GetCustomers, GetOrders, GetProducts, GetOrderItems).
        :param tool_name: Name of the tool to invoke.
        :param arguments: Dictionary of arguments (e.g. {'customerID': 6}).
        """
        response = self._mcp_request(
            "tools/call", {"name": tool_name, "arguments": arguments or {}}
        )

        if "error" in response:
            return f"Execution failed: {response['error']}"

        # Extract the content array from the JSON-RPC result
        content = response.get("result", {}).get("content", [])

        # Return as pretty JSON for the LLM to parse
        return json.dumps(content, indent=2)

